test('observer-record-shape',()=>{const p=document.createElement('div'),a=document.createTextNode('a'),b=document.createElement('b'),o=new MutationObserver(()=>{});o.observe(p,{childList:true,attributes:true,attributeOldValue:true});p.append(a);p.append(b);p.removeChild(a);p.setAttribute('x','1');for(const r of o.takeRecords())log('record',JSON.stringify([r.type,r.target===p,r.addedNodes.length,r.removedNodes.length,r.previousSibling===a,r.nextSibling===b,r.attributeName,r.attributeNamespace,r.oldValue,r instanceof MutationRecord,r.addedNodes instanceof NodeList,Array.isArray(r.addedNodes),Reflect.set(r,'type','other')]));log('observer keys',Object.keys(o).join(','));o.disconnect()});
